$ErrorActionPreference='Stop'
$project='C:\Projects\gympro-api'
$bin='C:\Program Files\PostgreSQL\18\bin'
$stamp=(Get-Date -Format 'yyyyMMddHHmmss')+'_'+[guid]::NewGuid().ToString('N').Substring(0,6)
$target='gympro_adopt_'+$stamp
$reference='gympro_bootstrap_'+$stamp
$report=Join-Path 'C:\Projects\gympro-backups' ('ledger-adoption-rehearsal-'+$stamp)
$createdTarget=$false;$createdReference=$false;$success=$false
$oldPassword=$env:PGPASSWORD;$oldOptions=$env:PGOPTIONS;$oldSsl=$env:PGSSLMODE
function Run([string]$Exe,[string[]]$Arguments,[string]$Step){
 Write-Host "CHECK: $Step" -ForegroundColor Cyan
 $old=$ErrorActionPreference
 try{$ErrorActionPreference='Continue';& $Exe @Arguments;$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old}
 [IO.File]::WriteAllText((Join-Path $report ($Step+'.exit-code.txt')),[string]$code)
 if($null -eq $code -or $code -ne 0){throw "Step failed: $Step (exit $code)"}
}
try{
 Set-Location $project
 foreach($name in @('pg_dump.exe','pg_restore.exe','createdb.exe','dropdb.exe','psql.exe')){if(-not(Test-Path (Join-Path $bin $name))){throw "PostgreSQL tool missing: $name"}}
 $node=(Get-Command node.exe -ErrorAction Stop).Source
 New-Item -ItemType Directory -Path $report | Out-Null
 $zip=Join-Path $report 'payload.zip';[IO.File]::WriteAllBytes($zip,[Convert]::FromBase64String(''))
 $payload=Join-Path $report 'payload';Expand-Archive $zip $payload
 $review=Get-Content (Join-Path $payload 'readiness-manifest.json') -Raw | ConvertFrom-Json
 foreach($entry in $review.sourceHashes){if((Get-FileHash (Join-Path $project $entry.file) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.sha256){throw "Source changed since reviewed checkpoint: $($entry.file)"}}
 $secure=Read-Host 'Local PostgreSQL postgres password' -AsSecureString
 $ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
 try{$env:PGPASSWORD=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr);$secure.Dispose()}
 $env:PGOPTIONS=$null;$env:PGSSLMODE='disable'
 $connection=@('-h','127.0.0.1','-p','5432','-U','postgres','-w')
 $archive=Join-Path $report 'gympro-before-adoption.dump'
 Write-Host 'The archive stays on this computer and includes working database records. Do not upload the dump.'
 Run (Join-Path $bin 'pg_dump.exe') ($connection+@('-d','gympro_saas','--format=custom','--file',$archive)) 'backup-working-database'
 Run (Join-Path $bin 'pg_restore.exe') @('--list',$archive) 'verify-archive-listing'
 Run (Join-Path $bin 'createdb.exe') ($connection+@('--template=template0',$target)) 'create-restored-copy';$createdTarget=$true
 Run (Join-Path $bin 'pg_restore.exe') ($connection+@('--exit-on-error','--single-transaction','-d',$target,$archive)) 'restore-copy'
 Run (Join-Path $bin 'createdb.exe') ($connection+@('--template=template0',$reference)) 'create-clean-reference';$createdReference=$true
 $common=$connection+@('-X','-q','-d',$reference,'-v','ON_ERROR_STOP=1')
 Run (Join-Path $bin 'psql.exe') ($common+@('--single-transaction','-f',(Join-Path $project 'sql\baseline-20261016\schema.sql'))) 'install-reference-baseline'
 # Existing cluster roles are reused; no cluster-role creation or changes.
 Run (Join-Path $bin 'psql.exe') ($common+@('-v',"target=$reference",'-f',(Join-Path $project 'sql\bootstrap-prerequisites-20261016\010-permissions.sql'))) 'seed-reference-permissions'
 foreach($file in @('0003_self_session_management.sql','0004_password_change.sql')){
  Run (Join-Path $bin 'psql.exe') ($common+@('--single-transaction','-f',(Join-Path $project ('sql\migrations\'+$file)))) ('reference-'+[IO.Path]::GetFileNameWithoutExtension($file))
 }
 Run $node @((Join-Path $payload 'verify-and-adopt.mjs'),$project,$target,$reference,$report,$payload) 'compare-and-rehearse-adoption'
 $results=Get-Content (Join-Path $report 'adoption-results.json') -Raw | ConvertFrom-Json
 if($results.success -ne $true -or $results.checkCount -ne 14 -or @($results.checks | Where-Object result -ne 'PASS').Count -ne 0){throw 'Adoption evidence incomplete.'}
 $success=$true
}catch{Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}finally{
 if($success){
  try{
   if($createdTarget){Run (Join-Path $bin 'dropdb.exe') ($connection+@($target)) 'remove-restored-copy';$createdTarget=$false}
   if($createdReference){Run (Join-Path $bin 'dropdb.exe') ($connection+@($reference)) 'remove-clean-reference';$createdReference=$false}
  }catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}
 }
 $env:PGPASSWORD=$oldPassword;$env:PGOPTIONS=$oldOptions;$env:PGSSLMODE=$oldSsl
}
if($success){
 try{
  $saved=Join-Path $project 'tools\adoption-rehearsal';New-Item -ItemType Directory -Path $saved -Force | Out-Null
  Copy-Item (Join-Path $payload 'verify-and-adopt.mjs') (Join-Path $saved 'verify-and-adopt.mjs') -Force
  Copy-Item $PSCommandPath (Join-Path $project 'scripts\completion-ledger-adoption-rehearsal.ps1') -Force
  [ordered]@{scope='Migration ledger adoption on restored copy';checksPassed=14;exactCatalogMatch=$true;concurrentApplyOnce=$true;immutableRetry=$true;checksumDriftRejected=$true;businessFingerprintsUnchanged=$true;existingFunctionsNotReplayed=$true;absentProvisioningMetadataInstalledOnlyInCopy=$true;temporaryDatabasesRemoved=$true;workingDatabaseChanged=$false;workingLedgerInstalled=$false;productionFeaturesEnabled=$false;kbzPayDeferred=$true;reportFolder=$report;verifiedAt=(Get-Date -Format o)} | ConvertTo-Json | Set-Content (Join-Path $report 'adoption-summary.json') -Encoding UTF8
  Copy-Item (Join-Path $report 'adoption-summary.json') (Join-Path $project 'docs\completion\ledger-adoption-rehearsal-summary.json') -Force
  Write-Host 'PASS: Restored-copy adoption, exact schema/security comparison, concurrency, retry, drift rejection and unchanged business content verified (14 checks).' -ForegroundColor Green
  Write-Host 'PASS: Temporary databases removed. Working database ledger and application source unchanged.'
  Write-Host 'PENDING: Reviewed live adoption. Recovery/MFA/audit production rollout remains separate. No UI change or Git commit.'
 }catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}
}
Write-Host "Reports and local database backup: $report"
if($createdTarget){Write-Host "Retained restored database: $target"}
if($createdReference){Write-Host "Retained reference database: $reference"}
Write-Host 'Do not upload database dump files. Send the terminal result; for failures send only the first error.'
if(-not $success){exit 1}
